def acts(key,coll=None):
    coll=coll or C[key]; out=[]
    for i,f in enumerate(F[key]):
        lab=f'{key}-{i}'
        if f[0]=='s':
            r={'type':f[1],'displayName':f[2]}
            if f[3]: r['helpText']=f[3]
            out.append({'label':lab,'create_collection_static_field':{'collection_id':coll,'request':r}})
        elif f[0]=='o':
            r={'type':'Option','displayName':f[1],'metadata':{'options':[{'name':o} for o in f[2]]}}
            if f[3]: r['helpText']=f[3]
            out.append({'label':lab,'create_collection_option_field':{'collection_id':coll,'request':r}})
        else:
            r={'type':'MultiReference' if f[3] else 'Reference','displayName':f[1],'metadata':{'collectionId':C[f[2]]}}
            if f[4]: r['helpText']=f[4]
            out.append({'label':lab,'create_collection_reference_field':{'collection_id':coll,'request':r}})
    return out
